<?php defined('BASEPATH') OR exit('No direct script access allowed'); include APPPATH . 'views/layouts/header.php'; include APPPATH . 'views/layouts/sidebar.php'; $readonly = $assignment->state === 'closed' || !$assessment || $assessment->status === 'finalized'; $version = $assessment ? (int) $assessment->version : 0; ?>
<div class="ami-panel"><div class="ami-panel-body"><h2 class="ami-section-title"><?php echo html_escape($assignment->source_package_code . ' — ' . $assignment->source_package_title); ?></h2><p><?php echo nl2br(html_escape($assignment->source_package_description ?: 'Deskripsi paket belum diisi.')); ?></p><?php if (!$readonly): ?><?php echo form_open('auditor/spmi/assignment/' . (int) $assignment->id . '/save'); ?><input type="hidden" name="version" value="<?php echo html_escape((string) $version); ?>"><?php endif; ?><?php foreach ($items as $item): ?><article class="card mb-3"><div class="card-body"><h3><?php echo html_escape((string) $item->display_order . '. ' . $item->question_code); ?></h3><p><?php echo nl2br(html_escape($item->question_text)); ?></p><p><strong>Instruksi bukti</strong><br><?php echo nl2br(html_escape($item->evidence_instruction)); ?></p><p><strong>Realisasi submitted</strong><br><?php echo nl2br(html_escape($item->assessment ? $item->assessment->realization_snapshot : '')); ?></p><div><strong>Rubrik</strong><?php foreach ($item->rubrics as $rubric): ?><div><?php echo html_escape((string) $rubric->score . ' — ' . $rubric->descriptor); ?></div><?php endforeach; ?></div><ul><?php foreach ($item->evidence as $evidence): ?><li><a href="<?php echo site_url('auditor/spmi/evidence/' . (int) $evidence->id . '/download'); ?>"><?php echo html_escape($evidence->original_name); ?></a></li><?php endforeach; ?></ul><?php $current_score = $item->assessment ? $item->assessment->score : ''; ?><label for="score-<?php echo (int) $item->id; ?>">Skor</label><select id="score-<?php echo (int) $item->id; ?>" name="assessment[<?php echo (int) $item->id; ?>][score]" <?php echo $readonly ? 'disabled' : ''; ?>><option value="">Pilih skor</option><?php for ($score = 1; $score <= 4; $score++): ?><option value="<?php echo $score; ?>" <?php echo (string) $current_score === (string) $score ? 'selected' : ''; ?>><?php echo $score; ?></option><?php endfor; ?></select><label for="finding-<?php echo (int) $item->id; ?>">Temuan</label><textarea id="finding-<?php echo (int) $item->id; ?>" name="assessment[<?php echo (int) $item->id; ?>][finding]" <?php echo $readonly ? 'readonly' : ''; ?>><?php echo html_escape($item->assessment ? $item->assessment->finding : ''); ?></textarea><label for="recommendation-<?php echo (int) $item->id; ?>">Rekomendasi</label><textarea id="recommendation-<?php echo (int) $item->id; ?>" name="assessment[<?php echo (int) $item->id; ?>][recommendation]" <?php echo $readonly ? 'readonly' : ''; ?>><?php echo html_escape($item->assessment ? $item->assessment->recommendation : ''); ?></textarea></div></article><?php endforeach; ?><?php if (!$readonly): ?><button type="submit">Simpan draft</button><button type="submit" formaction="<?php echo site_url('auditor/spmi/assignment/' . (int) $assignment->id . '/finalize'); ?>">Finalisasi</button><?php elseif ($assignment->state === 'closed'): ?><div class="alert alert-info">Siklus closed bersifat hanya-baca.</div><?php else: ?><div class="alert alert-info">Penilaian sudah difinalisasi dan bersifat hanya-baca.</div><?php endif; ?><?php if (!$readonly): ?><?php echo form_close(); ?><?php endif; ?></div></div>
<?php include APPPATH . 'views/layouts/footer.php'; ?>
